.drv-chain-ladder,.drv-chain-ladder *{box-sizing:border-box;}
.drv-chain-ladder{width:100%;max-width:380px;padding:9px 9px 7px;border-radius:11px;background:linear-gradient(180deg,#141826 0%,#0A0D14 100%);border:1px solid rgba(255,255,255,.075);color:#E4E9F4;font-family:ui-monospace,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums;line-height:1.25;}
.drv-chain-ladder-top{display:flex;align-items:baseline;gap:6px;}
.drv-chain-ladder-sym{font-size:12.5px;font-weight:700;letter-spacing:.02em;}
.drv-chain-ladder-ric{font-size:8px;color:#68738A;letter-spacing:.06em;}
.drv-chain-ladder-last{margin-left:auto;font-size:12.5px;font-weight:600;}
.drv-chain-ladder-chg{font-size:8.5px;color:#3FD08A;white-space:nowrap;}
.drv-chain-ladder-meta{display:flex;align-items:center;gap:7px;margin-top:3px;font-size:8px;letter-spacing:.05em;color:#79839A;text-transform:uppercase;}
.drv-chain-ladder-meta b{color:#C7D0E2;font-weight:600;}
.drv-chain-ladder-exp{color:#C7D0E2;}
.drv-chain-ladder-grow{flex:1;}
.drv-chain-ladder-live{color:#3FD08A;position:relative;padding-left:8px;}
.drv-chain-ladder-live::before{content:"";position:absolute;left:0;top:50%;width:4px;height:4px;margin-top:-2px;border-radius:50%;background:#3FD08A;animation:drv-chain-ladder-pulse 1.9s ease-in-out infinite;}
.drv-chain-ladder-band{display:grid;grid-template-columns:1fr 1fr;gap:44px;margin-top:7px;font-size:7.5px;letter-spacing:.16em;color:#5C6478;}
.drv-chain-ladder-bc{color:#7FA8E8;}
.drv-chain-ladder-bp{color:#D9899C;text-align:right;}
.drv-chain-ladder-hd,.drv-chain-ladder-row{display:grid;grid-template-columns:repeat(4,1fr) 32px repeat(4,1fr);align-items:center;column-gap:0;}
.drv-chain-ladder-hd{margin-top:2px;padding:0 0 3px;font-size:7.5px;letter-spacing:.08em;color:#5D6478;border-bottom:1px solid rgba(255,255,255,.08);}
.drv-chain-ladder-hd span{text-align:right;}
.drv-chain-ladder-hd .drv-chain-ladder-k{text-align:center;}
.drv-chain-ladder-scroll{max-height:132px;overflow-y:auto;overflow-x:hidden;margin-top:2px;outline:none;scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.16) transparent;}
.drv-chain-ladder-scroll::-webkit-scrollbar{width:4px;}
.drv-chain-ladder-scroll::-webkit-scrollbar-thumb{background:rgba(255,255,255,.16);border-radius:2px;}
.drv-chain-ladder-scroll::-webkit-scrollbar-track{background:transparent;}
.drv-chain-ladder-scroll:focus-visible{box-shadow:inset 0 0 0 1px rgba(96,165,250,.55);border-radius:4px;}
.drv-chain-ladder-row{font-size:9px;padding:1.5px 0;cursor:pointer;border-left:2px solid transparent;}
.drv-chain-ladder-row:hover{background:rgba(255,255,255,.035);}
.drv-chain-ladder-c{min-width:0;text-align:right;padding-right:1px;color:#B9C2D6;overflow:hidden;}
.drv-chain-ladder-dim{color:#6E7890;font-size:8.5px;}
.drv-chain-ladder-k{min-width:0;text-align:center;font-size:9px;font-weight:600;color:#E4E9F4;background:rgba(255,255,255,.04);}
.drv-chain-ladder-citm{background:rgba(96,165,250,.12);color:#D6E1F5;}
.drv-chain-ladder-pitm{background:rgba(226,120,145,.12);color:#F3DCE2;}
.drv-chain-ladder-atm{background:rgba(250,204,21,.07);border-left-color:#FACC15;}
.drv-chain-ladder-atm .drv-chain-ladder-k{color:#FACC15;background:rgba(250,204,21,.12);}
.drv-chain-ladder-on{background:rgba(96,165,250,.16);border-left-color:#60A5FA;}
.drv-chain-ladder-on .drv-chain-ladder-k{color:#EAF1FF;}
.drv-chain-ladder-up{color:#3FD08A;animation:drv-chain-ladder-flash-u .5s ease-out;}
.drv-chain-ladder-dn{color:#F0748A;animation:drv-chain-ladder-flash-d .5s ease-out;}
.drv-chain-ladder-foot{margin-top:5px;padding-top:5px;border-top:1px solid rgba(255,255,255,.08);}
.drv-chain-ladder-l1{display:flex;justify-content:space-between;align-items:baseline;font-size:9.5px;}
.drv-chain-ladder-tick{color:#E4E9F4;font-weight:600;}
.drv-chain-ladder-mkt{color:#FACC15;}
.drv-chain-ladder-l2{margin-top:2px;font-size:7.5px;color:#79839A;}
.drv-chain-ladder-gk{display:block;white-space:nowrap;}
.drv-chain-ladder-l3{display:flex;justify-content:flex-end;margin-top:2px;font-size:6.5px;letter-spacing:.06em;color:#4E5668;}
.drv-chain-ladder-stage{white-space:nowrap;}
.drv-chain-ladder-armed{color:#3FD08A;}
@keyframes drv-chain-ladder-pulse{0%,100%{opacity:1;}50%{opacity:.25;}}
@keyframes drv-chain-ladder-flash-u{0%{background:rgba(63,208,138,.30);}100%{background:transparent;}}
@keyframes drv-chain-ladder-flash-d{0%{background:rgba(240,116,138,.30);}100%{background:transparent;}}
@media (prefers-reduced-motion: reduce){
.drv-chain-ladder-live::before{animation:none;}
.drv-chain-ladder-up,.drv-chain-ladder-dn{animation:none;}
}

js:
var rows = Array.prototype.slice.call(root.querySelectorAll('.drv-chain-ladder-row'));
var box = root.querySelector('.drv-chain-ladder-scroll');
var tick = root.querySelector('.drv-chain-ladder-tick');
var mkt = root.querySelector('.drv-chain-ladder-mkt');
var gk = root.querySelector('.drv-chain-ladder-gk');
var hint = root.querySelector('.drv-chain-ladder-stage');
var sel = 5, side = 'C';
function nf(n){ return n.toLocaleString('en-US'); }
function paint(){
  for (var i = 0; i < rows.length; i++) rows[i].classList.toggle('drv-chain-ladder-on', i === sel);
  var r = rows[sel];
  var call = side === 'C';
  var b = r.querySelector(call ? '.drv-chain-ladder-cb' : '.drv-chain-ladder-pb').textContent;
  var a = r.querySelector(call ? '.drv-chain-ladder-ca' : '.drv-chain-ladder-pa').textContent;
  tick.textContent = 'AAPL 18SEP26 ' + r.getAttribute('data-k') + ' ' + side;
  mkt.textContent = b + ' / ' + a;
  var mid = ((parseFloat(b) + parseFloat(a)) / 2).toFixed(3);
  gk.textContent = 'mid ' + mid + ' · Δ ' + r.getAttribute(call ? 'data-cd' : 'data-pd') +
    ' · Γ ' + r.getAttribute('data-g') + ' · ' + r.getAttribute(call ? 'data-civ' : 'data-piv') +
    'v · ' + nf(parseInt(r.getAttribute(call ? 'data-cv' : 'data-pv'), 10));
}
for (var i = 0; i < rows.length; i++) {
  (function(n){
    rows[n].addEventListener('click', function(e){
      sel = n;
      var box2 = rows[n].getBoundingClientRect();
      side = (e.clientX - box2.left) / box2.width < 0.5 ? 'C' : 'P';
      paint();
    });
  })(i);
}
box.addEventListener('keydown', function(e){
  var k = e.key;
  if (k === 'ArrowDown') { sel = Math.min(rows.length - 1, sel + 1); }
  else if (k === 'ArrowUp') { sel = Math.max(0, sel - 1); }
  else if (k === 'ArrowLeft') { side = 'C'; }
  else if (k === 'ArrowRight') { side = 'P'; }
  else if (k === 'Enter') {
    hint.textContent = 'STAGED · 1 lot';
    hint.classList.add('drv-chain-ladder-armed');
  } else { return; }
  e.preventDefault();
  paint();
  rows[sel].scrollIntoView({ block: 'nearest' });
});
paint();
var t = setInterval(function(){
  if (!root.isConnected) { clearInterval(t); return; }
  var n = Math.floor(Math.random() * rows.length);
  var r = rows[n];
  var pair = Math.random() < 0.5 ? ['.drv-chain-ladder-cb', '.drv-chain-ladder-ca']
                                 : ['.drv-chain-ladder-pb', '.drv-chain-ladder-pa'];
  var bE = r.querySelector(pair[0]), aE = r.querySelector(pair[1]);
  var b = parseFloat(bE.textContent), a = parseFloat(aE.textContent);
  var step = Math.random() < 0.5 ? -0.01 : 0.01;
  if (b + step <= 0.01) step = 0.01;
  var cls = step > 0 ? 'drv-chain-ladder-up' : 'drv-chain-ladder-dn';
  bE.textContent = (b + step).toFixed(2);
  aE.textContent = (a + step).toFixed(2);
  bE.classList.add(cls); aE.classList.add(cls);
  setTimeout(function(){ bE.classList.remove(cls); aE.classList.remove(cls); }, 520);
  if (n === sel) paint();
}, 900);

