js:
var NETD = -30, SPOT = 232.48, GAM = 139348, VEG = 4329;
var lad = root.querySelector('.drv-greeks-book-lad');
var mode = 'spot';
function money(v){
  var s = v > 0 ? '+' : (v < 0 ? '−' : ' ');
  return s + '$' + Math.abs(Math.round(v)).toLocaleString('en-US');
}
function render(){
  var xs = [-3, -2, -1, 0, 1, 2, 3], out = [], vals = [], i;
  for (i = 0; i < xs.length; i++) {
    var x = xs[i], p;
    if (mode === 'spot') p = (NETD * SPOT * x + 0.5 * GAM * x * x) / 100;
    else p = VEG * x;
    vals.push(p);
  }
  var mx = 0;
  for (i = 0; i < vals.length; i++) mx = Math.max(mx, Math.abs(vals[i]));
  if (mx === 0) mx = 1;
  for (i = 0; i < xs.length; i++) {
    var v = vals[i], w = Math.abs(v) / mx * 50, neg = v < 0;
    var lbl = (xs[i] > 0 ? '+' : (xs[i] < 0 ? '−' : ' ')) + Math.abs(xs[i]) + (mode === 'spot' ? '%' : 'v');
    out.push('<div class="drv-greeks-book-lrow' + (neg ? ' drv-greeks-book-lneg' : '') +
      (xs[i] === 0 ? ' drv-greeks-book-lzero' : '') + '">' +
      '<span class="drv-greeks-book-lx">' + lbl + '</span>' +
      '<span class="drv-greeks-book-lbar"><i class="drv-greeks-book-lfill" style="' +
      (neg ? 'left:' + (50 - w) + '%;' : 'left:50%;') + 'width:' + w + '%"></i>' +
      '<i class="drv-greeks-book-lmid"></i></span>' +
      '<span class="drv-greeks-book-lv ' + (v > 0 ? 'drv-greeks-book-up' : (v < 0 ? 'drv-greeks-book-dn' : 'drv-greeks-book-fl')) +
      '">' + money(v) + '</span></div>');
  }
  lad.innerHTML = out.join('');
}
var sws = root.querySelectorAll('.drv-greeks-book-sw');
for (var i = 0; i < sws.length; i++) {
  (function(b){
    b.addEventListener('click', function(){
      mode = b.getAttribute('data-mode');
      for (var j = 0; j < sws.length; j++) sws[j].classList.toggle('drv-greeks-book-swon', sws[j] === b);
      render();
    });
  })(sws[i]);
}
sws[0].classList.add('drv-greeks-book-swon');
var tabs = root.querySelectorAll('.drv-greeks-book-tab');
var views = root.querySelectorAll('.drv-greeks-book-view');
for (var t = 0; t < tabs.length; t++) {
  (function(b){
    b.addEventListener('click', function(){
      var v = b.getAttribute('data-view'), j;
      for (j = 0; j < tabs.length; j++) {
        tabs[j].classList.toggle('drv-greeks-book-sel', tabs[j] === b);
        tabs[j].setAttribute('aria-selected', tabs[j] === b ? 'true' : 'false');
      }
      for (j = 0; j < views.length; j++)
        views[j].classList.toggle('drv-greeks-book-hide', views[j].getAttribute('data-view') !== v);
    });
  })(tabs[t]);
}
render();

