js:
var plot = root.querySelector('.drv-vol-smile-plot');
var dots = root.querySelectorAll('.drv-vol-smile-dot');
var cross = root.querySelector('.drv-vol-smile-cross');
var cur = root.querySelector('.drv-vol-smile-cur');
var rb = root.querySelector('.drv-vol-smile-rb');
var rk = root.querySelector('.drv-vol-smile-rk');
var riv = root.querySelector('.drv-vol-smile-riv');
var rd = root.querySelector('.drv-vol-smile-rd');
var pts = plot.getAttribute('data-pts').split(';').map(function(s){ return s.split('|'); });
var xs = [], ys = [], i;
for (i = 0; i < dots.length; i++) { xs.push(parseFloat(dots[i].getAttribute('cx'))); ys.push(parseFloat(dots[i].getAttribute('cy'))); }
var idx = 3;
cross.setAttribute('x1', xs[0]); cross.setAttribute('x2', xs[0]);
cur.setAttribute('cx', xs[0]); cur.setAttribute('cy', ys[0]);
function show(n){
  idx = Math.max(0, Math.min(pts.length - 1, n));
  cross.setAttribute('transform', 'translate(' + (xs[idx] - xs[0]).toFixed(1) + ',0)');
  cur.setAttribute('transform', 'translate(' + (xs[idx] - xs[0]).toFixed(1) + ',' + (ys[idx] - ys[0]).toFixed(1) + ')');
  var p = pts[idx];
  rb.textContent = p[0];
  rk.textContent = 'K ' + p[1];
  riv.textContent = p[2] + 'v';
  var d = parseFloat(p[3]);
  rd.textContent = (d > 0 ? '+' : '−') + Math.abs(d).toFixed(2) + ' d/d';
