}
function fromX(cx){
  var r = plot.getBoundingClientRect();
  var vx = (cx - r.left) / r.width * 300;
  var best = 0, bd = 1e9;
  for (var j = 0; j < xs.length; j++) { var d = Math.abs(xs[j] - vx); if (d < bd) { bd = d; best = j; } }
  show(best);
}
plot.addEventListener('pointermove', function(e){ fromX(e.clientX); });
plot.addEventListener('keydown', function(e){
  if (e.key === 'ArrowLeft') { show(idx - 1); e.preventDefault(); }
  else if (e.key === 'ArrowRight') { show(idx + 1); e.preventDefault(); }
});
