var D = [[4,20.95,null],[11,21.72,22.15],[18,22.64,24.01],[46,25.90,27.79],[81,25.35,24.61],[109,25.80,27.06],[200,26.55,27.42],[508,27.20,27.61]];
var line = root.querySelector('.drv-term-vol-line');
var area = root.querySelector('.drv-term-vol-area');
var dots = root.querySelectorAll('.drv-term-vol-dot');
var selc = root.querySelector('.drv-term-vol-sel');
var rows = root.querySelectorAll('.drv-term-vol-row');
var btns = root.querySelectorAll('.drv-term-vol-b');
function tx(d){ return 24 + (Math.sqrt(d) - 2) / (Math.sqrt(508) - 2) * 268; }
function ty(v){ return 86 - (v - 20) / 8 * 74; }
function build(series){
  var pts = [], i;
  for (i = 0; i < D.length; i++) {
    var v = series === 'spot' ? D[i][1] : D[i][2];
    if (v === null) continue;
    pts.push([tx(D[i][0]), ty(v)]);
  }
  var s = pts.map(function(p){ return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' ');
  line.setAttribute('points', s);
  area.setAttribute('d', 'M' + pts[0][0].toFixed(1) + ',90 L' +
    pts.map(function(p){ return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' L') +
    ' L' + pts[pts.length - 1][0].toFixed(1) + ',90 Z');
  for (i = 0; i < dots.length; i++) {
    var vv = series === 'spot' ? D[i][1] : D[i][2];
    if (vv === null) { dots[i].setAttribute('r', '0'); }
    else { dots[i].setAttribute('r', '2.3'); dots[i].setAttribute('cy', ty(vv).toFixed(1)); }
  }
  return series;
}
var cur = 'spot';
for (var b = 0; b < btns.length; b++) {
  (function(el){
    el.addEventListener('click', function(){
      cur = el.getAttribute('data-s');
      for (var j = 0; j < btns.length; j++) btns[j].classList.toggle('drv-term-vol-bon', btns[j] === el);
      build(cur);
      selc.classList.remove('drv-term-vol-selon');
    });
  })(btns[b]);
}
for (var r = 0; r < rows.length; r++) {
  (function(el, i){
    el.addEventListener('click', function(){
      for (var j = 0; j < rows.length; j++) rows[j].classList.toggle('drv-term-vol-rowon', j === i);
      var v = cur === 'spot' ? D[i][1] : D[i][2];
      if (v === null) { selc.classList.remove('drv-term-vol-selon'); return; }
      selc.setAttribute('cx', tx(D[i][0]).toFixed(1));
      selc.setAttribute('cy', ty(v).toFixed(1));
      selc.classList.add('drv-term-vol-selon');
    });
  })(rows[r], r);
}
build('spot');

