var STR = [
  {n:'IRON CONDOR 220/225/240/245', legs:[[1,'P',220,0.98],[-1,'P',225,1.84],[-1,'C',240,1.86],[1,'C',245,0.84]]},
  {n:'CALL SPREAD 235/240',         legs:[[1,'C',235,3.69],[-1,'C',240,1.86]]},
  {n:'LONG STRADDLE 232.5',         legs:[[1,'C',232.5,4.92],[1,'P',232.5,4.44]]},
  {n:'PUT RATIO 1x2 232.5/225',     legs:[[1,'P',232.5,4.44],[-2,'P',225,1.84]]},
  {n:'RISK REVERSAL 225/240',       legs:[[-1,'P',225,1.84],[1,'C',240,1.89]]}
];
var LOT = 10, LO = 208, HI = 258, SPOT = 232.48;
var svg = root.querySelector('.drv-payoff-strat-svg');
var plot = root.querySelector('.drv-payoff-strat-plot');
var line = root.querySelector('.drv-payoff-strat-line');
var fp = root.querySelector('.drv-payoff-strat-fp');
var fl = root.querySelector('.drv-payoff-strat-fl');
var zero = root.querySelector('.drv-payoff-strat-zero');
var ticks = root.querySelector('.drv-payoff-strat-ticks');
var curd = root.querySelector('.drv-payoff-strat-cur');
var legbox = root.querySelector('.drv-payoff-strat-legs');
var stats = root.querySelectorAll('.drv-payoff-strat-s');
var chips = root.querySelectorAll('.drv-payoff-strat-chip');
var beline = root.querySelector('.drv-payoff-strat-be');
var ru = root.querySelector('.drv-payoff-strat-ru');
var rp = root.querySelector('.drv-payoff-strat-rp');
var cur = 0, geo = null;
function pay(legs, s){
  var v = 0;
  for (var i = 0; i < legs.length; i++) {
    var L = legs[i], it = L[1] === 'C' ? Math.max(s - L[2], 0) : Math.max(L[2] - s, 0);
    v += L[0] * (it - L[3]);
  }
  return v;
}
function money(v){ return (v > 0 ? '+$' : (v < 0 ? '−$' : '$')) + Math.abs(Math.round(v)).toLocaleString('en-US'); }
function X(s){ return 14 + (s - LO) / (HI - LO) * 280; }
function render(k){
  cur = k;
  var st = STR[k], legs = st.legs, i;
  var xs = [], j;
  for (j = 0; j <= 100; j++) xs.push(LO + j * (HI - LO) / 100);
  for (i = 0; i < legs.length; i++) if (legs[i][2] > LO && legs[i][2] < HI) xs.push(legs[i][2]);
  var bes = [];
  xs.sort(function(a, b){ return a - b; });
  var ys = xs.map(function(s){ return pay(legs, s); });
  for (j = 1; j < xs.length; j++) {
    if ((ys[j - 1] < 0 && ys[j] > 0) || (ys[j - 1] > 0 && ys[j] < 0)) {
      var t = -ys[j - 1] / (ys[j] - ys[j - 1]);
      bes.push(xs[j - 1] + t * (xs[j] - xs[j - 1]));
    }
  }
  for (j = 0; j < bes.length; j++) { xs.push(bes[j]); }
  xs.sort(function(a, b){ return a - b; });
  ys = xs.map(function(s){ return pay(legs, s); });
  var pmax = Math.max.apply(null, ys), pmin = Math.min.apply(null, ys);
  var pad = (pmax - pmin) * 0.14 || 1;
  var top = pmax + pad, bot = pmin - pad;
  function Y(p){ return 12 + (top - p) / (top - bot) * 72; }
  geo = { xs: xs, ys: ys, Y: Y, legs: legs };
  var pl = [], up = [], dn = [];
  for (j = 0; j < xs.length; j++) {
    pl.push(X(xs[j]).toFixed(1) + ',' + Y(ys[j]).toFixed(1));
    up.push(X(xs[j]).toFixed(1) + ',' + Y(Math.max(ys[j], 0)).toFixed(1));
    dn.push(X(xs[j]).toFixed(1) + ',' + Y(Math.min(ys[j], 0)).toFixed(1));
  }
  var z = Y(0).toFixed(1);
  line.setAttribute('points', pl.join(' '));
  fp.setAttribute('points', X(LO).toFixed(1) + ',' + z + ' ' + up.join(' ') + ' ' + X(HI).toFixed(1) + ',' + z);
  fl.setAttribute('points', X(LO).toFixed(1) + ',' + z + ' ' + dn.join(' ') + ' ' + X(HI).toFixed(1) + ',' + z);
  zero.setAttribute('y1', z); zero.setAttribute('y2', z);
  var tk = '';
  for (i = 0; i < legs.length; i++) {
    var xx = X(legs[i][2]).toFixed(1);
    tk += '<line class="drv-payoff-strat-tk" x1="' + xx + '" y1="86" x2="' + xx + '" y2="90"></line>';
  }
  ticks.innerHTML = tk;
  var rows = '', net = 0;
  for (i = 0; i < legs.length; i++) {
    var L = legs[i], cf = -L[0] * L[3] * 100 * LOT;
    net += cf;
    rows += '<div class="drv-payoff-strat-lg">' +
      '<span class="drv-payoff-strat-q ' + (L[0] > 0 ? 'drv-payoff-strat-up' : 'drv-payoff-strat-dn') + '">' +
      (L[0] > 0 ? '+' : '−') + Math.abs(L[0] * LOT) + '</span>' +
      '<span class="drv-payoff-strat-nm">18SEP26 ' + L[2] + ' ' + L[1] + '</span>' +
      '<span class="drv-payoff-strat-px">' + L[3].toFixed(2) + '</span>' +
      '<span class="drv-payoff-strat-sd">' + (L[0] > 0 ? 'PAY ASK' : 'HIT BID') + '</span>' +
      '<span class="drv-payoff-strat-cf ' + (cf > 0 ? 'drv-payoff-strat-up' : 'drv-payoff-strat-dn') + '">' + money(cf) + '</span></div>';
  }
  legbox.innerHTML = rows;
  var maxP = pmax * 100 * LOT, maxL = pmin * 100 * LOT;
  var slopeHi = pay(legs, HI) - pay(legs, HI - 1);
  var slopeLo = pay(legs, LO + 1) - pay(legs, LO);
  var openP = slopeHi > 0.001 || slopeLo < -0.001;
  var openL = slopeHi < -0.001 || slopeLo > 0.001;
  stats[0].querySelector('b').textContent = money(net);
  stats[0].querySelector('b').className = net > 0 ? 'drv-payoff-strat-up' : 'drv-payoff-strat-dn';
  stats[0].querySelector('i').textContent = net > 0 ? 'credit' : 'debit';
  stats[1].querySelector('b').textContent = openP ? 'UNCAPPED' : money(maxP);
  stats[1].querySelector('b').className = 'drv-payoff-strat-up';
  stats[1].querySelector('i').textContent = openP ? 'unbounded' : pmax.toFixed(2) + ' pt';
  stats[2].querySelector('b').textContent = openL ? 'UNCAPPED' : money(maxL);
  stats[2].querySelector('b').className = 'drv-payoff-strat-dn';
  stats[2].querySelector('i').textContent = openL ? 'unbounded' : Math.abs(pmin).toFixed(2) + ' pt';
  var rr = (openL || openP || pmin === 0) ? '—' : (Math.abs(pmax / pmin)).toFixed(2);
  stats[3].querySelector('b').textContent = rr;
  stats[3].querySelector('i').textContent = bes.length + ' B/E';
  beline.innerHTML = 'B/E ' + (bes.length ? bes.map(function(b){ return '<b>' + b.toFixed(2) + '</b>'; }).join(' · ') : '<b>none in range</b>') +
    '<span class="drv-payoff-strat-hint">' + st.n + '</span>';
  at(SPOT);
}
function at(s){
  s = Math.max(LO, Math.min(HI, s));
  var v = pay(geo.legs, s) * 100 * LOT;
  curd.setAttribute('cx', X(s).toFixed(1));
  curd.setAttribute('cy', geo.Y(v / 100 / LOT).toFixed(1));
  ru.textContent = 'underlying ' + s.toFixed(2);
  rp.textContent = 'P&L ' + money(v);
  rp.className = 'drv-payoff-strat-rp ' + (v > 0 ? 'drv-payoff-strat-up' : (v < 0 ? 'drv-payoff-strat-dn' : ''));
}
plot.addEventListener('pointermove', function(e){
  var r = svg.getBoundingClientRect();
  var vx = (e.clientX - r.left) / r.width * 300;
  at(LO + (vx - 14) / 280 * (HI - LO));
});
plot.addEventListener('pointerleave', function(){ at(SPOT); });
for (var c = 0; c < chips.length; c++) {
  (function(el, i){
    el.addEventListener('click', function(){ pick(i); });
  })(chips[c], c);
}
function pick(i){
  for (var j = 0; j < chips.length; j++) {
    chips[j].classList.toggle('drv-payoff-strat-on', j === i);
    chips[j].setAttribute('aria-selected', j === i ? 'true' : 'false');
  }
  render(i);
}
root.querySelector('.drv-payoff-strat-chips').addEventListener('keydown', function(e){
  if (e.key === 'ArrowRight') { pick((cur + 1) % STR.length); e.preventDefault(); }
  else if (e.key === 'ArrowLeft') { pick((cur + STR.length - 1) % STR.length); e.preventDefault(); }
});
render(0);

