var rows = root.querySelectorAll('.drv-oi-strikes-row');
var btns = root.querySelectorAll('.drv-oi-strikes-b');
var scale = root.querySelector('.drv-oi-strikes-scale');
var hp = root.querySelector('.drv-oi-strikes-hp');
var hc = root.querySelector('.drv-oi-strikes-hc');
function nf(v){ return Math.abs(v).toLocaleString('en-US'); }
function draw(mode){
  var mx = 0, i, c, p;
  for (i = 0; i < rows.length; i++) {
    c = parseInt(rows[i].getAttribute(mode === 'oi' ? 'data-c' : 'data-dc'), 10);
    p = parseInt(rows[i].getAttribute(mode === 'oi' ? 'data-p' : 'data-dp'), 10);
    mx = Math.max(mx, Math.abs(c), Math.abs(p));
  }
  if (!mx) mx = 1;
  for (i = 0; i < rows.length; i++) {
    c = parseInt(rows[i].getAttribute(mode === 'oi' ? 'data-c' : 'data-dc'), 10);
    p = parseInt(rows[i].getAttribute(mode === 'oi' ? 'data-p' : 'data-dp'), 10);
    var cv = rows[i].querySelector('.drv-oi-strikes-cv');
    var pv = rows[i].querySelector('.drv-oi-strikes-pv');
    var cf = rows[i].querySelector('.drv-oi-strikes-cf');
    var pf = rows[i].querySelector('.drv-oi-strikes-pf');
    cv.textContent = (mode === 'oi' ? '' : (c > 0 ? '+' : (c < 0 ? '−' : ''))) + nf(c);
    pv.textContent = (mode === 'oi' ? '' : (p > 0 ? '+' : (p < 0 ? '−' : ''))) + nf(p);
    cf.style.width = (Math.abs(c) / mx * 100).toFixed(1) + '%';
    pf.style.width = (Math.abs(p) / mx * 100).toFixed(1) + '%';
    cf.classList.toggle('drv-oi-strikes-neg', c < 0);
    pf.classList.toggle('drv-oi-strikes-neg', p < 0);
  }
  scale.textContent = 'scale ' + mx.toLocaleString('en-US');
  hp.textContent = mode === 'oi' ? 'PUT OI' : 'PUT ΔOI';
  hc.textContent = mode === 'oi' ? 'CALL OI' : 'CALL ΔOI';
}
for (var b = 0; b < btns.length; b++) {
  (function(el){
    el.addEventListener('click', function(){
      for (var j = 0; j < btns.length; j++) btns[j].classList.toggle('drv-oi-strikes-bon', btns[j] === el);
      draw(el.getAttribute('data-m'));
    });
  })(btns[b]);
}
draw('oi');

