var CV = [1284,1092,1416,1338,1187,1502,1621,1394,1268,1155,1338,1489,1712,1604,1421,1296,1180,1352,1497,1640];
var PV = [918,842,962,1015,894,1024,1181,1076,998,901,1013,1067,1158,1122,1071,989,936,1094,1216,1398];
var R = [], i;
for (i = 0; i < CV.length; i++) R.push(PV[i] / CV[i]);
var last = R[R.length - 1], prev = R[R.length - 2];
var mean = 0;
for (i = 0; i < R.length; i++) mean += R[i];
mean /= R.length;
var mn = Math.min.apply(null, R), mx = Math.max.apply(null, R);
var below = 0;
for (i = 0; i < R.length; i++) if (R[i] < last) below++;
var pctile = Math.round(below / R.length * 100);
var lo = mn - 0.02, hi = mx + 0.02;
function sx(n){ return 4 + n * (292 / 19); }
function sy(v){ return 42 - (v - lo) / (hi - lo) * 36; }
var pts = [];
for (i = 0; i < R.length; i++) pts.push(sx(i).toFixed(1) + ',' + sy(R[i]).toFixed(1));
root.querySelector('.drv-pcr-gauge-hist').setAttribute('points', pts.join(' '));
root.querySelector('.drv-pcr-gauge-mean').setAttribute('y1', sy(mean).toFixed(1));
root.querySelector('.drv-pcr-gauge-mean').setAttribute('y2', sy(mean).toFixed(1));
root.querySelector('.drv-pcr-gauge-todaydot').setAttribute('cy', sy(last).toFixed(1));
root.querySelector('.drv-pcr-gauge-meanl').textContent = 'mean ' + mean.toFixed(3);
root.querySelector('.drv-pcr-gauge-v1').textContent = last.toFixed(3);
root.querySelector('.drv-pcr-gauge-v2').textContent = mean.toFixed(3);
root.querySelector('.drv-pcr-gauge-v3').textContent = mn.toFixed(2) + '–' + mx.toFixed(2);
root.querySelector('.drv-pcr-gauge-v4').textContent = String(pctile);
var totv = CV[CV.length - 1] + PV[PV.length - 1];
root.querySelector('.drv-pcr-gauge-v5').textContent = totv.toLocaleString('en-US') + 'k';
var cs = CV[CV.length - 1] / totv * 100, ps = 100 - cs;
var scEl = root.querySelector('.drv-pcr-gauge-sc'), spEl = root.querySelector('.drv-pcr-gauge-sp');
scEl.style.width = cs.toFixed(2) + '%'; scEl.textContent = 'CALL ' + cs.toFixed(2) + '%';
spEl.style.width = ps.toFixed(2) + '%'; spEl.textContent = 'PUT ' + ps.toFixed(2) + '%';
var d = last - prev;
var chg = root.querySelector('.drv-pcr-gauge-chg');
chg.textContent = (d >= 0 ? '▲ +' : '▼ −') + Math.abs(d).toFixed(2) + ' d/d';
var zones = [[0.60, 'COMPLACENT'], [0.80, 'NEUTRAL'], [1.00, 'CAUTIOUS'], [99, 'FEARFUL']];
var zn = 'FEARFUL';
for (i = 0; i < zones.length; i++) { if (last < zones[i][0]) { zn = zones[i][1]; break; } }
root.querySelector('.drv-pcr-gauge-zone').textContent = zn;
var zls = root.querySelectorAll('.drv-pcr-gauge-zl span');
for (i = 0; i < zls.length; i++) zls[i].classList.toggle('drv-pcr-gauge-zon', zls[i].textContent === zn);
var needle = root.querySelector('.drv-pcr-gauge-needle');
var target = Math.max(0, Math.min(100, (last - 0.40) / 0.90 * 100));
var big = root.querySelector('.drv-pcr-gauge-big');
needle.style.left = '0%';
void needle.offsetWidth;
needle.style.left = target.toFixed(1) + '%';
var done = false, t0 = 0;
function finish(){
  if (done) return;
  done = true;
  big.textContent = last.toFixed(2);
  needle.style.left = target.toFixed(1) + '%';
}
function step(ts){
  if (!root.isConnected || done) return;
  if (!t0) t0 = ts;
  var k = Math.min(1, (ts - t0) / 700);
  big.textContent = (last * (1 - Math.pow(1 - k, 3))).toFixed(2);
  if (k < 1) requestAnimationFrame(step); else finish();
}
requestAnimationFrame(step);
setTimeout(finish, 900);

