js:
var rows = root.querySelectorAll('.drv-expiry-pin-row');
var cols = root.querySelectorAll('.drv-expiry-pin-col');
var det = root.querySelector('.drv-expiry-pin-det');
function risk(dist, dte){
  if (Math.abs(dist) < 0.25 && dte <= 7) return 'HIGH';
  if (Math.abs(dist) < 1.50 && dte <= 21) return 'MED';
  return 'LOW';
}
function pick(i){
  var j;
  for (j = 0; j < rows.length; j++) rows[j].classList.toggle('drv-expiry-pin-rowon', j === i);
  for (j = 0; j < cols.length; j++) cols[j].classList.toggle('drv-expiry-pin-colon', j === i);
  var r = rows[i];
  var dist = parseFloat(r.getAttribute('data-d'));
  var dte = parseInt(r.querySelector('.drv-expiry-pin-n').textContent, 10);
  var lv = risk(dist, dte);
  det.innerHTML = r.getAttribute('data-e') + ' · ' + r.getAttribute('data-oi') + 'k OI · $' +
    parseInt(r.getAttribute('data-no'), 10).toLocaleString('en-US') + 'mm · pin ' +
    parseFloat(r.getAttribute('data-pin')).toFixed(2) + ' (' + (dist > 0 ? '+' : '−') +
    Math.abs(dist).toFixed(2) + '%) · Γ +$' + r.getAttribute('data-g') + 'mm/1% · <b class="drv-expiry-pin-' +
    lv.toLowerCase() + '">' + lv + ' PIN</b>';
}
for (var i = 0; i < rows.length; i++) {
  (function(n){
    rows[n].addEventListener('click', function(){ pick(n); });
    if (cols[n]) cols[n].addEventListener('click', function(){ pick(n); });
  })(i);
}
